// trades/packs/sources.ts — the registry every pack cites (Doc 23 §4).
//
// `license` decides what a pack may store from a source:
//   public_domain / gov_open      facts + numbers (paraphrase preferred)
//   manufacturer_public           paraphrase + cite; numbers OK with citation
//   association_public            paraphrase + cite
//   platform_estimate             our own expert baseline — any value citing it must be confidence 'estimate'
//   proprietary_ref_only          section numbers + ≤10-word titles + our paraphrase. NEVER tables/numbers.
// Add a source once here, then cite its id. `pack:verify-sources` HEAD-checks every url (bot-blocked
// government sites answer 403 to scripts — that is reported, not failed).

export type SourceLicense =
  | 'public_domain' | 'gov_open' | 'manufacturer_public' | 'association_public'
  | 'platform_estimate' | 'proprietary_ref_only';

export interface SourceDef {
  title: string;
  url: string;
  publisher: string;
  license: SourceLicense;
  retrieved: string;      // YYYY-MM-DD
  note?: string;
}

const ECFR_1926 = 'https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926';
const ecfr1926 = (subpart: string, title: string): SourceDef => ({
  title: `29 CFR 1926 Subpart ${subpart} — ${title}`,
  url: `${ECFR_1926}/subpart-${subpart}`,
  publisher: 'OSHA / eCFR', license: 'public_domain', retrieved: '2026-10-08',
});

